import sys

def main():
    try:
        value = float(sys.argv[1])
        result = value + 1000
        print(result)
    except (IndexError, ValueError):
        print("Please provide a valid number as a command line argument.", file=sys.stderr)
        return 1
    return 0

if __name__ == "__main__":
    exit(main())

